import{_ as a,o as n,c as l,a3 as c}from"./chunks/framework.MGD2uYU7.js";const f=JSON.parse('{"title":"SC-27 — Lịch xem nhà","description":"","frontmatter":{"title":"SC-27 — Lịch xem nhà"},"headers":[],"relativePath":"wireframes/user/sc-27-lich-xem-nha.md","filePath":"wireframes/user/sc-27-lich-xem-nha.md","lastUpdated":1791606799000}'),i={name:"wireframes/user/sc-27-lich-xem-nha.md"};function t(p,s,h,d,e,o){return n(),l("div",null,[...s[0]||(s[0]=[c('<h1 id="sc-27-—-lich-xem-nha-2-tab-minh-đat-minh-nhan" tabindex="-1">SC-27 — Lịch xem nhà (2 tab: mình đặt / mình nhận) <a class="header-anchor" href="#sc-27-—-lich-xem-nha-2-tab-minh-đat-minh-nhan" aria-label="Permalink to &quot;SC-27 — Lịch xem nhà (2 tab: mình đặt / mình nhận)&quot;">​</a></h1><p><span class="wf-badge info">ƯU TIÊN TRUNG BÌNH</span> <span class="wf-badge info">Route: /lich-xem-nha</span> <span class="wf-badge muted">Nguồn: docs/05 §3 SC-27 · docs/03 UC-04 · docs/08 BR-VW-01..04 · docs/02 FR-VW-01..04 · docs/06 §5</span></p><p><strong>Ai xem màn này</strong>: Người mua đã KYC APPROVED muốn xem nhà trực tiếp (tab &quot;Mình đặt&quot;) · chủ nhà nhận yêu cầu và phải phản hồi (tab &quot;Mình nhận&quot;) · CS/ADMIN chỉ giám sát ở SC-26 admin, không dùng màn này. <strong>Cảm xúc cần thiết kế</strong>: &quot;đặt được lịch mà không bị hệ thống làm khó&quot;. Picker phải chặn sai ngay từ đầu (không cho chọn rồi mới báo lỗi), và người đặt luôn biết <strong>đang chờ ai, tới khi nào</strong>. Với chủ nhà: đây là việc phải làm trong 24 giờ, cần thấy SLA và 3 nút rõ ràng. <strong>Ví dụ số dùng trong bản vẽ</strong>: hôm nay <code>10/10/2026 15:20 (GMT+7)</code> → cửa sổ đặt lịch <code>[11/10/2026 15:20 → 24/10/2026 15:20]</code>, giờ cho phép <code>08:00–20:00</code>. Lịch đang chờ: <code>vwr_01J9ZK6E2G</code> (CT1-B07.02 — NOXH HP-380) slot <code>20/10/2026 14:00</code>. Hạn mức: tối đa <strong>3 lịch chờ</strong>, hiện <strong>2/3</strong>.</p><h2 id="_1-desktop-—-tab-minh-đat" tabindex="-1">1. Desktop — tab &quot;Mình đặt&quot; <a class="header-anchor" href="#_1-desktop-—-tab-minh-đat" aria-label="Permalink to &quot;1. Desktop — tab &quot;Mình đặt&quot;&quot;">​</a></h2><div class="wf"><div class="wf-screen"><div class="wf-browser-bar"><span class="wf-dot"></span><span class="wf-dot"></span><span class="wf-dot"></span><span class="wf-url">anphuc.vn/lich-xem-nha</span></div><div class="wf-body"><div class="wf-header"><span class="wf-logo">AnPhuc</span><span class="wf-nav"><span class="active">Mua nhà</span><span>Đấu giá</span><span>Bảng gói</span><span>Hướng dẫn</span></span><span class="wf-header-actions"><span class="wf-bell">🔔<span class="count">2</span></span><span class="wf-avatar">TV</span></span></div><div class="wf-container"><div class="wf-breadcrumb">Tài khoản › <b>Lịch xem nhà</b></div><div class="wf-row between middle wrap"><span class="wf-title lg">Lịch xem nhà</span><span class="wf-small">Đang chờ: <b>2 / 3 lịch</b> <span class="wf-callout">1</span></span></div><div class="wf-tabs"><span class="wf-tab active">Mình đặt (3)</span><span class="wf-tab">Mình nhận (2)</span></div><div class="wf-row" style="align-items:flex-start;"><div class="wf-grow wf-col" style="gap:10px;"><div class="wf-card" style="border-color:var(--wf-accent);"><div class="pad wf-col" style="gap:8px;"><div class="wf-row between middle wrap"><div class="wf-row middle wrap" style="gap:8px;"><span class="wf-badge info">CONFIRMED — ĐÃ XÁC NHẬN</span><span class="wf-title">CT2-A18.05 — NOXH HP-380</span></div><span class="wf-small">Mã lịch <span class="wf-trace">vwr_01J9ZK5D8F</span></span></div><div class="wf-row wrap" style="gap:16px;"><div class="wf-col" style="gap:2px;"><span class="wf-small wf-muted">Lịch hẹn (GMT+7)</span><span class="wf-strong">18/10/2026 09:00</span></div><div class="wf-col" style="gap:2px;"><span class="wf-small wf-muted">Chủ nhà</span><span class="wf-small">Nguyễn Văn A · CCCD đã xác minh ✓</span></div><div class="wf-col" style="gap:2px;"><span class="wf-small wf-muted">Địa chỉ</span><span class="wf-small">380 Võ Nguyên Giáp, Vĩnh Niệm, Lê Chân, Hải Phòng</span></div></div><div class="wf-note" style="margin:0;">Chủ nhà đã xác nhận lúc 11/10/2026 09:14. Đến đúng giờ, mang theo CCCD để đối chiếu. Cần đổi lịch? Gọi <b>1900-xxx</b>. <span class="wf-callout">2</span></div><div class="wf-row wrap" style="gap:8px;"><span class="wf-btn">Xem tin → SC-03</span><span class="wf-btn ghost sm">Thêm vào lịch điện thoại</span></div></div></div><div class="wf-card"><div class="pad wf-col" style="gap:8px;"><div class="wf-row between middle wrap"><div class="wf-row middle wrap" style="gap:8px;"><span class="wf-badge warn">PENDING — CHỜ CHỦ NHÀ</span><span class="wf-title">CT1-B07.02 — NOXH HP-380</span></div><span class="wf-sla soon">chờ 05:12 / SLA 24 giờ</span></div><div class="wf-row wrap" style="gap:16px;"><div class="wf-col" style="gap:2px;"><span class="wf-small wf-muted">Lịch hẹn (GMT+7)</span><span class="wf-strong">20/10/2026 14:00</span></div><div class="wf-col" style="gap:2px;"><span class="wf-small wf-muted">Gửi lúc</span><span class="wf-small">10/10/2026 10:08</span></div><div class="wf-col" style="gap:2px;"><span class="wf-small wf-muted">Chủ nhà</span><span class="wf-small">Chưa phản hồi</span></div></div><div class="wf-row wrap" style="gap:8px;"><span class="wf-btn ghost sm">Hủy yêu cầu <span class="wf-callout">3</span></span><span class="wf-btn ghost sm">Đặt giờ khác</span></div></div></div><div class="wf-card"><div class="pad wf-col" style="gap:6px;"><div class="wf-row between middle wrap"><div class="wf-row middle wrap" style="gap:8px;"><span class="wf-badge ok">COMPLETED — ĐÃ XEM</span><span class="wf-title">HH2-A03.11 — NOXH AQ-120</span></div><span class="wf-small">05/10/2026 16:00</span></div><span class="wf-small">Chủ nhà đánh dấu hoàn tất 05/10/2026 17:40. Tin vẫn còn bán — bạn có thể đặt lịch lần nữa? Không: mỗi người chỉ 1 lịch đang chờ/đã xác nhận cho cùng một tin.</span></div></div><div class="wf-card"><div class="pad wf-col" style="gap:6px;"><div class="wf-row between middle wrap"><div class="wf-row middle wrap" style="gap:8px;"><span class="wf-badge danger">REJECTED — CHỦ NHÀ TỪ CHỐI</span><span class="wf-title">CT3-C01.04 — NOXH HP-380</span></div><span class="wf-small">04/10/2026 11:20</span></div><div class="wf-note" style="margin:0;border-color:var(--wf-danger);"><b>Lý do chủ nhà đưa ra:</b> &quot;Cuối tuần này tôi đi công tác, chưa thể mở nhà. Bạn đặt lại tuần sau giúp tôi.&quot;</div><span class="wf-btn ghost sm">Đặt lại lịch khác</span></div></div></div><div class="wf-sidebar"><div class="wf-card"><div class="pad wf-col" style="gap:8px;"><span class="wf-small wf-strong">ĐẶT LỊCH XEM NHÀ MỚI</span><span class="wf-small wf-muted">Chọn tin đang bán (LISTED) → chọn ngày → chọn giờ.</span><div class="wf-search">Tìm tin hoặc mã căn…</div><div class="wf-card flat"><div class="pad wf-col" style="gap:2px;"><span class="wf-small">CT2-A18.05 — NOXH HP-380</span><span class="wf-small wf-muted">72 m² · 2 PN · 1 WC · tầng 18 · Sổ hồng</span><span class="wf-money">1.250.000.000 ₫</span></div></div><span class="wf-btn primary block sm">Chọn lịch cho tin này</span><div class="wf-col" style="gap:4px;margin-top:4px;"><span class="wf-small wf-strong">QUY TẮC ĐẶT LỊCH</span><span class="wf-small">· Trước ít nhất <b>24 giờ</b>, không quá <b>14 ngày</b></span><span class="wf-small">· Trong khung <b>08:00–20:00</b> (GMT+7)</span><span class="wf-small">· Tối đa <b>3 lịch chờ</b> cùng lúc</span><span class="wf-small">· Mỗi tin chỉ <b>1 lịch</b> đang chờ/đã xác nhận</span><span class="wf-small">· Cần đã xác minh CCCD</span></div></div></div></div></div></div><div class="wf-footer"><span>AnPhucRealEstate — sàn NOXH được vận hành bởi An Phuc</span><span>Quy chế đấu giá</span><span>CSKH 1900-xxx</span></div></div></div></div><div class="wf-legend"><div class="t">Chú thích hành vi (trace: docs/03 UC-04 · docs/08 BR-VW-01..04 · docs/02 FR-VW-01..03 · docs/06 §5)</div><ol><li><span class="num">1</span><span>Bộ đếm &quot;2 / 3 lịch chờ&quot; luôn hiện ở đầu tab — chỉ đếm trạng thái PENDING (CONFIRMED/COMPLETED/REJECTED/CANCELLED/EXPIRED không chiếm suất). Khi 3/3 thì nút đặt mới bị thay bằng thông báo hạn mức (mục 2). <span class="ref">BR-VW-02</span></span></li><li><span class="num">2</span><span>Mỗi card lịch hiện: tin + mã căn, slot giờ GMT+7, chủ nhà + trạng thái xác minh, mã lịch, trạng thái, hành động theo trạng thái. Địa chỉ đầy đủ chỉ hiện khi <b>CONFIRMED trở lên</b> (tránh lộ địa chỉ cho lịch chưa được chủ nhà đồng ý). <span class="ref">FR-VW-03</span> <span class="ref">docs/07 §2.8</span></span></li><li><span class="num">3</span><span>Hủy chỉ khả thi khi còn PENDING → trạng thái CANCELLED. Sau khi chủ nhà đã CONFIRMED thì không có nút tự hủy — thay bằng &quot;gọi CS 1900-xxx&quot;. <b>Điểm cần PM chốt</b>: docs/03 AF-1 chỉ nói hủy trước confirm, chưa quy định đổi lịch sau confirm. <span class="ref">UC-04 AF-1</span></span></li><li><span class="num">4</span><span>REJECTED luôn kèm <b>lý do chủ nhà nhập</b> (bắt buộc 5–500 ký tự) và nút đặt lại — không để người mua tự đoán vì sao bị từ chối. <span class="ref">FR-VW-02</span></span></li><li><span class="num">5</span><span>Tab chỉ hiện &quot;Mình nhận&quot; khi user có tin đăng; user chưa đăng tin nào thì tab này ẩn hoặc hiện empty riêng — không hiện tab trống vô nghĩa. <span class="ref">docs/05 §7</span></span></li></ol></div><h2 id="_2-picker-chon-ngay-gio-—-slot-bi-chan-amp-trang-thai-cham-han-muc-3" tabindex="-1">2. Picker chọn ngày/giờ — slot bị chặn &amp; trạng thái chạm hạn mức 3 <a class="header-anchor" href="#_2-picker-chon-ngay-gio-—-slot-bi-chan-amp-trang-thai-cham-han-muc-3" aria-label="Permalink to &quot;2. Picker chọn ngày/giờ — slot bị chặn &amp;amp; trạng thái chạm hạn mức 3&quot;">​</a></h2><div class="wf"><div class="wf-grid"><div class="wf-col"><span class="wf-state-label">PICKER — HÔM NAY 10/10/2026 15:20</span><div class="wf-card"><div class="pad wf-col" style="gap:10px;"><span class="wf-small wf-strong">CHỌN NGÀY (cửa sổ 11/10 → 24/10/2026)</span><div class="wf-row wrap" style="gap:6px;"><span class="wf-btn disabled sm">T6 10/10 — hôm nay</span><span class="wf-btn disabled sm">T7 11/10 (trước 15:20)</span><span class="wf-btn sm">CN 12/10</span><span class="wf-btn primary sm">T2 13/10</span><span class="wf-btn sm">T3 14/10</span><span class="wf-btn sm">…</span><span class="wf-btn sm">T6 24/10 (tới 15:20)</span><span class="wf-btn disabled sm">T7 25/10 — quá 14 ngày</span></div><span class="wf-small wf-strong">CHỌN GIỜ — NGÀY 13/10/2026</span><div class="wf-row wrap" style="gap:6px;"><span class="wf-btn disabled sm">06:00</span><span class="wf-btn disabled sm">07:00</span><span class="wf-btn sm">08:00</span><span class="wf-btn sm">09:00</span><span class="wf-btn sm">10:00</span><span class="wf-btn primary sm">14:00</span><span class="wf-btn sm">16:00</span><span class="wf-btn sm">19:00</span><span class="wf-btn disabled sm">20:30</span><span class="wf-btn disabled sm">21:00</span></div><span class="wf-small wf-muted">Ô mờ = không chọn được (kèm tooltip lý do: &quot;Trước 24 giờ&quot; / &quot;Ngoài khung 08:00–20:00&quot; / &quot;Quá 14 ngày&quot;). <span class="wf-callout danger">6</span></span><div class="wf-row between middle" style="border-top:1px solid var(--wf-line);padding-top:8px;"><div class="wf-col" style="gap:2px;"><span class="wf-small">Lịch đã chọn</span><span class="wf-strong">13/10/2026 14:00 (GMT+7)</span></div><span class="wf-btn primary">GỬI YÊU CẦU</span></div><span class="wf-small wf-muted">Sau khi gửi: PENDING, chủ nhà nhận thông báo, SLA phản hồi 24 giờ.</span></div></div><div class="wf-card flat" style="margin-top:10px;"><div class="pad wf-col" style="gap:4px;"><span class="wf-small wf-strong">Nếu server vẫn trả 422 (slot đổi giữa lúc user chọn)</span><div class="wf-field-error">Chọn lịch trước 24h và trong 14 ngày (08:00–20:00)</div><span class="wf-small">Message nguyên văn docs/06 §5 (<code>VIEWING_SLOT_INVALID</code>) — hiện inline ngay dưới picker, đồng thời tính lại cửa sổ theo giờ server (<code>X-Server-Time</code>). <span class="ref">UC-04 EF-1</span></span></div></div></div><div class="wf-col"><span class="wf-state-label">CHẠM HẠN MỨC 3 LỊCH CHỜ</span><div class="wf-card" style="border-color:var(--wf-warn);"><div class="pad wf-col" style="gap:8px;"><div class="wf-row between middle"><span class="wf-small wf-strong">LỊCH ĐANG CHỜ</span><span class="wf-badge warn">3 / 3</span></div><div class="wf-row between"><span class="wf-text">CT1-B07.02 — 20/10/2026 14:00</span><span class="wf-btn ghost sm">Hủy</span></div><div class="wf-row between"><span class="wf-text">CT2-A20.08 — 21/10/2026 09:00</span><span class="wf-btn ghost sm">Hủy</span></div><div class="wf-row between"><span class="wf-text">HH2-A03.11 — 22/10/2026 10:00</span><span class="wf-btn ghost sm">Hủy</span></div><div class="wf-field-error">Tối đa 3 lịch chờ — hủy lịch cũ để đặt mới</div><span class="wf-btn disabled block">ĐẶT LỊCH MỚI (đã đủ 3 lịch chờ)</span><span class="wf-small wf-muted">Message nguyên văn docs/06 §5 (<code>VIEWING_LIMIT</code>). Hiện <b>trước khi</b> user mở picker, kèm 3 lịch đang chiếm suất để họ tự chọn cái cần hủy. <span class="wf-callout">7</span></span></div></div><div class="wf-card flat" style="margin-top:10px;"><div class="pad wf-col" style="gap:4px;"><span class="wf-small wf-strong">Tin không còn nhận lịch (409)</span><span class="wf-small">&quot;Tin này không còn nhận đặt lịch — căn đã được đặt cọc hoặc đã bán.&quot; Kèm link về tin (SC-03) và các tin cùng dự án. <b>Lưu ý:</b> docs/06 §5 chưa có message cho nhánh này (<code>LISTING_LOCKED</code> 409 theo BR-VW-04) — cần bổ sung bảng copy trước khi code. <span class="ref">BR-VW-04</span> <span class="ref">UC-04 EF-3</span></span></div></div><div class="wf-card flat" style="margin-top:10px;"><div class="pad wf-col" style="gap:4px;"><span class="wf-small wf-strong">Đã có lịch chờ cho đúng tin này (409)</span><span class="wf-small">Ràng buộc 1 lịch PENDING/CONFIRMED cho mỗi cặp người đặt × tin. UI nên disable nút &quot;Đặt lịch&quot; ngay trên SC-03 và trỏ về lịch đang có, thay vì để user gửi rồi mới lỗi. <span class="ref">BR-VW-02</span></span></div></div><div class="wf-card flat" style="margin-top:10px;"><div class="pad wf-col" style="gap:4px;"><span class="wf-small wf-strong">Chưa xác minh CCCD (403)</span><div class="wf-field-error">Bạn cần xác minh danh tính (CCCD) trước khi thao tác này</div><span class="wf-small">Message nguyên văn docs/06 §5 (<code>KYC_REQUIRED</code>) + CTA &quot;Xác minh ngay → SC-21&quot;. Vẫn xem được danh sách lịch cũ. <span class="ref">FR-VW-01</span> <span class="ref">BR-KYC-08</span></span></div></div></div></div></div><div class="wf-legend"><div class="t">Chú thích</div><ol><li><span class="num">6</span><span>Chặn ngay tại picker là yêu cầu chính của màn này: ngày hôm nay/ngày mai trước mốc +24h, giờ ngoài 08:00–20:00, ngày vượt 14 ngày đều <b>disabled có lý do</b>. Validate server-side vẫn là nguồn chân lý (BR-VW-01) — picker chỉ là lớp chặn sớm. Mốc +24h tính theo <b>giờ server</b>, không theo đồng hồ máy khách. <span class="ref">BR-VW-01</span> <span class="ref">FR-VW-01</span></span></li><li><span class="num">7</span><span>Không cho user mở picker rồi mới báo &quot;hết suất&quot; — hiện trạng thái 3/3 kèm danh sách để hủy. Nút &quot;Hủy&quot; phải có dialog xác nhận ngắn (không undo được). <span class="ref">BR-VW-02</span> <span class="ref">UC-04 EF-2</span></span></li></ol></div><h2 id="_3-desktop-—-tab-minh-nhan-chu-nha-sla-phan-hoi" tabindex="-1">3. Desktop — tab &quot;Mình nhận&quot; (chủ nhà) + SLA phản hồi <a class="header-anchor" href="#_3-desktop-—-tab-minh-nhan-chu-nha-sla-phan-hoi" aria-label="Permalink to &quot;3. Desktop — tab &quot;Mình nhận&quot; (chủ nhà) + SLA phản hồi&quot;">​</a></h2><div class="wf"><div class="wf-col"><div class="wf-tabs"><span class="wf-tab">Mình đặt (3)</span><span class="wf-tab active">Mình nhận (2)</span></div><div class="wf-row between middle wrap"><span class="wf-small">Yêu cầu xem các tin bạn đăng · phản hồi trong <b>24 giờ</b> (mục tiêu vận hành)</span><span class="wf-small wf-muted">Lọc: <b>Chờ phản hồi (2)</b> · Đã xác nhận (1) · Lịch sử</span></div><div class="wf-grid cols-2"><div class="wf-card" style="border-color:var(--wf-warn);"><div class="pad wf-col" style="gap:8px;"><div class="wf-row between middle wrap"><span class="wf-badge warn">PENDING — CHỜ BẠN</span><span class="wf-sla soon">còn 02:15 / 24 giờ</span></div><span class="wf-title">CT1-B07.02 — NOXH HP-380</span><div class="wf-row wrap" style="gap:16px;"><div class="wf-col" style="gap:2px;"><span class="wf-small wf-muted">Người đặt</span><span class="wf-small">Trần Thị B · CCCD đã xác minh ✓</span></div><div class="wf-col" style="gap:2px;"><span class="wf-small wf-muted">Giờ đề nghị (GMT+7)</span><span class="wf-strong">13/10/2026 14:00</span></div><div class="wf-col" style="gap:2px;"><span class="wf-small wf-muted">Gửi lúc</span><span class="wf-small">10/10/2026 10:08</span></div></div><div class="wf-row wrap" style="gap:8px;"><span class="wf-btn ok">Xác nhận</span><span class="wf-btn danger ghost">Từ chối… <span class="wf-callout">8</span></span></div><span class="wf-small wf-muted">Không phản hồi: hệ thống gửi nhắc sau 24 giờ; quá giờ hẹn + 2 giờ mà chưa đánh dấu hoàn tất thì lịch tự chuyển EXPIRED. <span class="ref">BR-VW-03</span></span></div></div><div class="wf-card"><div class="pad wf-col" style="gap:8px;"><div class="wf-row between middle wrap"><span class="wf-badge info">CONFIRMED — ĐÃ XÁC NHẬN</span><span class="wf-sla ok">còn 2 ngày 18:40 tới giờ hẹn</span></div><span class="wf-title">CT2-A18.05 — NOXH HP-380</span><div class="wf-row wrap" style="gap:16px;"><div class="wf-col" style="gap:2px;"><span class="wf-small wf-muted">Người đặt</span><span class="wf-small">Trần Văn C · CCCD đã xác minh ✓</span></div><div class="wf-col" style="gap:2px;"><span class="wf-small wf-muted">Giờ hẹn (GMT+7)</span><span class="wf-strong">18/10/2026 09:00</span></div><div class="wf-col" style="gap:2px;"><span class="wf-small wf-muted">Bạn xác nhận lúc</span><span class="wf-small">11/10/2026 09:14</span></div></div><div class="wf-row wrap" style="gap:8px;"><span class="wf-btn primary">Đánh dấu hoàn tất</span><span class="wf-btn ghost sm">Liên hệ CS 1900-xxx</span></div><span class="wf-small wf-muted">&quot;Hoàn tất&quot; chỉ bấm được sau giờ hẹn; trước giờ hẹn nút disabled kèm chữ giải thích. <span class="wf-callout">9</span></span></div></div></div><div class="wf-grid cols-3"><div class="wf-col"><span class="wf-state-label">SLA CÒN NHIỀU</span><div class="wf-card"><div class="pad wf-col" style="gap:6px;"><span class="wf-sla ok">còn 18:40 / 24 giờ</span><span class="wf-small">Card viền thường. Không cần nhắc.</span></div></div></div><div class="wf-col"><span class="wf-state-label">SLA SẮP HẾT</span><div class="wf-card" style="border-color:var(--wf-warn);"><div class="pad wf-col" style="gap:6px;"><span class="wf-sla soon">còn 02:15 / 24 giờ</span><span class="wf-small">Viền warn + đã gửi NTF nhắc cho chủ nhà.</span></div></div></div><div class="wf-col"><span class="wf-state-label">QUÁ SLA</span><div class="wf-card" style="border-color:var(--wf-danger);"><div class="pad wf-col" style="gap:6px;"><span class="wf-sla over">quá 06:12 — chưa phản hồi</span><span class="wf-small">Vẫn cho xác nhận/từ chối (chưa EXPIRED vì chưa quá giờ hẹn + 2h). Người đặt thấy &quot;chủ nhà phản hồi trễ&quot; + gợi ý hủy. <span class="wf-callout danger">10</span></span></div></div></div></div></div></div><div class="wf-legend"><div class="t">Chú thích</div><ol><li><span class="num">8</span><span>Hai hành động chính của chủ nhà: <b>Xác nhận</b> (không cần lý do, chuyển CONFIRMED, NTF cả hai phía) và <b>Từ chối…</b> (mở modal bắt buộc nhập lý do — mục 4). Không có nút &quot;sửa giờ hẹn&quot; trong v1; muốn đổi giờ thì từ chối kèm lý do, người mua đặt lại. <span class="ref">FR-VW-02</span> <span class="ref">FR-VW-03</span></span></li><li><span class="num">9</span><span>&quot;Đánh dấu hoàn tất&quot; là bước kết thúc có chủ đích (COMPLETED) — nếu chủ nhà quên, job sẽ tự EXPIRED sau giờ hẹn + 2 giờ. UI phải làm rõ hai kết cục này khác nhau, và nhắc chủ nhà bấm hoàn tất sau buổi xem. <span class="ref">BR-VW-03</span> <span class="ref">UC-04 MF-4</span></span></li><li><span class="num">10</span><span>Quá SLA 24 giờ <b>không khóa</b> hành động của chủ nhà (không có BR nào cấm) — chỉ đổi sắc thái và nhắc. Đừng tự tiện disable nút; nếu PM muốn siết thì cần bổ sung BR trên docs/08 trước. <span class="ref">BR-VW-03</span> <span class="ref">UC-04 EF-4</span></span></li><li><span class="num">11</span><span>Tab &quot;Mình nhận&quot; không hiện thông tin liên hệ cá nhân (số điện thoại) của người đặt — kết nối qua CS khi cần, tránh lộ dữ liệu ngoài phạm vi lịch xem. <span class="ref">docs/05 §7</span></span></li></ol></div><h2 id="_4-modal-tu-choi-ly-do-bat-buoc-5–500-ky-tu" tabindex="-1">4. Modal từ chối (lý do bắt buộc 5–500 ký tự) <a class="header-anchor" href="#_4-modal-tu-choi-ly-do-bat-buoc-5–500-ky-tu" aria-label="Permalink to &quot;4. Modal từ chối (lý do bắt buộc 5–500 ký tự)&quot;">​</a></h2><div class="wf"><div class="wf-grid"><div class="wf-col"><span class="wf-state-label">A — CHƯA NHẬP LÝ DO (nút khóa)</span><div class="wf-modal-overlay"><div class="wf-modal"><div class="head"><span class="wf-title">Từ chối yêu cầu xem nhà</span><span class="wf-btn ghost sm">Đóng</span></div><div class="wf-col" style="gap:10px;"><div class="wf-card flat"><div class="pad wf-col" style="gap:2px;"><span class="wf-small">CT1-B07.02 — NOXH HP-380</span><span class="wf-small wf-muted">Trần Thị B · đề nghị 13/10/2026 14:00 (GMT+7)</span></div></div><span class="wf-small wf-strong">Lý do từ chối (người đặt sẽ đọc được) <span class="wf-callout danger">12</span></span><div class="wf-input error" style="min-height:64px;">|</div><div class="wf-row between"><span class="wf-small wf-muted">Tối thiểu 5 ký tự</span><span class="wf-small wf-muted">0 / 500</span></div><div class="wf-field-error">Vui lòng nhập lý do (5–500 ký tự)</div><span class="wf-btn danger disabled block">GỬI TỪ CHỐI</span><span class="wf-btn ghost block sm">Quay lại</span></div></div></div></div><div class="wf-col"><span class="wf-state-label">B — ĐÃ NHẬP LÝ DO (nút mở)</span><div class="wf-modal-overlay"><div class="wf-modal"><div class="head"><span class="wf-title">Từ chối yêu cầu xem nhà</span><span class="wf-btn ghost sm">Đóng</span></div><div class="wf-col" style="gap:10px;"><div class="wf-card flat"><div class="pad wf-col" style="gap:2px;"><span class="wf-small">CT1-B07.02 — NOXH HP-380</span><span class="wf-small wf-muted">Trần Thị B · đề nghị 13/10/2026 14:00 (GMT+7)</span></div></div><span class="wf-small wf-strong">Lý do từ chối (người đặt sẽ đọc được)</span><div class="wf-input filled" style="min-height:64px;">Cuối tuần này tôi đi công tác, chưa thể mở nhà. Bạn đặt lại tuần sau giúp tôi.</div><div class="wf-row between"><span class="wf-small wf-muted">Người đặt nhận thông báo ngay</span><span class="wf-small wf-muted">92 / 500</span></div><span class="wf-btn danger block">GỬI TỪ CHỐI</span><span class="wf-note" style="margin:0;">Sau khi gửi: trạng thái REJECTED, ghi <code>respondedAt</code>, không hoàn/không trừ gì (xem nhà miễn phí). Người đặt có thể đặt giờ khác cho tin này.</span></div></div></div><div class="wf-card flat" style="margin-top:10px;"><div class="pad wf-col" style="gap:4px;"><span class="wf-small wf-strong">Dialog hủy phía người mua</span><span class="wf-small">&quot;Hủy lịch CT1-B07.02 ngày 20/10/2026 14:00? Chủ nhà sẽ được thông báo. Không hoàn tác được.&quot; — hai nút <b>Hủy yêu cầu</b> / <b>Giữ lại</b>.</span></div></div></div></div></div><div class="wf-legend"><div class="t">Chú thích</div><ol><li><span class="num">12</span><span>Lý do là <b>bắt buộc</b> và dài 5–500 ký tự (khớp <code>reject_reason varchar(500)</code>); nút gửi disabled tới khi hợp lệ, kèm bộ đếm ký tự. Nói rõ &quot;người đặt sẽ đọc được&quot; để chủ nhà không viết lý do khiếm nhã. Không có sẵn danh sách lý do mẫu trong docs — nếu designer muốn thêm chip gợi ý thì phải được PM duyệt và không thay thế ô tự nhập. <span class="ref">FR-VW-02</span> <span class="ref">docs/07 §2.8</span></span></li><li><span class="num">13</span><span>Mọi chuyển trạng thái đều NTF cho cả hai phía (PENDING → CONFIRMED/REJECTED/CANCELLED/COMPLETED/EXPIRED) — UI không cần tự dựng kênh thông báo riêng, chỉ cần hiển thị đúng trạng thái sau refresh/poll. <span class="ref">FR-VW-03</span></span></li></ol></div><h2 id="_5-sau-trang-thai-cua-mot-lich" tabindex="-1">5. Sáu trạng thái của một lịch <a class="header-anchor" href="#_5-sau-trang-thai-cua-mot-lich" aria-label="Permalink to &quot;5. Sáu trạng thái của một lịch&quot;">​</a></h2><div class="wf"><div class="wf-grid cols-3"><div class="wf-card"><div class="pad wf-col" style="gap:4px;"><span class="wf-badge warn">PENDING</span><span class="wf-small">Vừa gửi, chờ chủ nhà (SLA 24 giờ). Người đặt có nút <b>Hủy</b>. Chiếm 1/3 suất lịch chờ.</span></div></div><div class="wf-card"><div class="pad wf-col" style="gap:4px;"><span class="wf-badge info">CONFIRMED</span><span class="wf-small">Chủ nhà đồng ý. Hiện địa chỉ đầy đủ + nhắc trước giờ hẹn. Vẫn chiếm suất tới khi kết thúc.</span></div></div><div class="wf-card"><div class="pad wf-col" style="gap:4px;"><span class="wf-badge ok">COMPLETED</span><span class="wf-small">Chủ nhà bấm hoàn tất sau buổi xem. Không còn hành động nào ngoài xem lại chi tiết.</span></div></div><div class="wf-card"><div class="pad wf-col" style="gap:4px;"><span class="wf-badge danger">REJECTED</span><span class="wf-small">Chủ nhà từ chối kèm lý do bắt buộc. CTA &quot;Đặt lại lịch khác&quot;.</span></div></div><div class="wf-card"><div class="pad wf-col" style="gap:4px;"><span class="wf-badge muted">CANCELLED</span><span class="wf-small">Người đặt tự hủy khi còn PENDING. Trả lại suất lịch chờ ngay.</span></div></div><div class="wf-card"><div class="pad wf-col" style="gap:4px;"><span class="wf-badge muted">EXPIRED</span><span class="wf-small">Quá giờ hẹn + 2 giờ mà chưa hoàn tất (job tự chuyển). Ghi chú trung tính: &quot;Buổi xem đã qua mà chưa được đánh dấu hoàn tất&quot;.</span></div></div></div></div><div class="wf-legend"><div class="t">Chú thích</div><ol><li><span class="num">14</span><span>Đủ 6 giá trị <code>ViewingState</code>: PENDING · CONFIRMED · COMPLETED · REJECTED · CANCELLED · EXPIRED. Badge màu thống nhất với các màn khác (warn = chờ, info = đang diễn ra, ok = xong, danger = bị từ chối, muted = đã đóng). EXPIRED không phải lỗi của ai — câu chữ phải trung tính. <span class="ref">docs/07 §3</span> <span class="ref">BR-VW-03</span></span></li></ol></div><h2 id="_6-mobile-360px" tabindex="-1">6. Mobile 360px <a class="header-anchor" href="#_6-mobile-360px" aria-label="Permalink to &quot;6. Mobile 360px&quot;">​</a></h2><div class="wf"><div class="wf-row" style="justify-content:center;gap:20px;flex-wrap:wrap;"><div><span class="wf-state-label">MOBILE — TAB &quot;MÌNH ĐẶT&quot; + PICKER</span><div class="wf-mobile"><div class="wf-mobile-bar"><span>9:41</span><span>▮▮▮ ⌁ ▰</span></div><div class="wf-header" style="padding:8px 12px;"><span class="wf-logo">AnPhuc</span><span class="wf-bell">🔔<span class="count">2</span></span></div><div class="wf-tabs" style="margin:8px 12px 0;"><span class="wf-tab active">Mình đặt (3)</span><span class="wf-tab">Mình nhận (2)</span></div><div class="wf-container" style="padding:12px;"><div class="wf-row between middle"><span class="wf-small">Đang chờ</span><span class="wf-badge warn">2 / 3</span></div><div class="wf-card" style="margin-top:8px;border-color:var(--wf-accent);"><div class="pad wf-col" style="gap:6px;"><span class="wf-badge info">CONFIRMED</span><span class="wf-title">CT2-A18.05 — NOXH HP-380</span><span class="wf-small wf-strong">18/10/2026 09:00 (GMT+7)</span><span class="wf-small">Chủ nhà Nguyễn Văn A · đã xác minh ✓</span><span class="wf-btn sm block">Xem chỉ đường</span></div></div><div class="wf-card" style="margin-top:8px;"><div class="pad wf-col" style="gap:6px;"><span class="wf-badge warn">PENDING — CHỜ CHỦ NHÀ</span><span class="wf-title">CT1-B07.02 — NOXH HP-380</span><span class="wf-small wf-strong">20/10/2026 14:00 (GMT+7)</span><span class="wf-sla soon">chờ 05:12 / SLA 24 giờ</span><span class="wf-btn ghost sm block">Hủy yêu cầu</span></div></div><div class="wf-card" style="margin-top:10px;"><div class="pad wf-col" style="gap:8px;"><span class="wf-small wf-strong">ĐẶT LỊCH MỚI — CT2-A18.05</span><div class="wf-row wrap" style="gap:6px;"><span class="wf-btn disabled sm">10/10</span><span class="wf-btn disabled sm">11/10</span><span class="wf-btn primary sm">13/10</span><span class="wf-btn sm">14/10</span><span class="wf-btn disabled sm">25/10</span></div><div class="wf-row wrap" style="gap:6px;"><span class="wf-btn disabled sm">07:00</span><span class="wf-btn sm">08:00</span><span class="wf-btn primary sm">14:00</span><span class="wf-btn disabled sm">21:00</span></div><span class="wf-small wf-muted">Ô mờ: trước 24h · ngoài 08:00–20:00 · quá 14 ngày</span></div></div></div><div class="wf-col" style="position:sticky;bottom:0;background:#fff;border-top:1px solid var(--wf-line);padding:10px 12px;"><span class="wf-btn primary block">GỬI YÊU CẦU 13/10/2026 14:00</span></div></div></div><div><span class="wf-state-label">MOBILE — TAB &quot;MÌNH NHẬN&quot; + LÝ DO TỪ CHỐI</span><div class="wf-mobile"><div class="wf-mobile-bar"><span>9:41</span><span>▮▮▮ ⌁ ▰</span></div><div class="wf-header" style="padding:8px 12px;"><span class="wf-logo">AnPhuc</span><span class="wf-bell">🔔<span class="count">2</span></span></div><div class="wf-tabs" style="margin:8px 12px 0;"><span class="wf-tab">Mình đặt (3)</span><span class="wf-tab active">Mình nhận (2)</span></div><div class="wf-container" style="padding:12px;"><div class="wf-card" style="border-color:var(--wf-warn);"><div class="pad wf-col" style="gap:6px;"><div class="wf-row between middle"><span class="wf-badge warn">CHỜ BẠN</span><span class="wf-sla soon">còn 02:15</span></div><span class="wf-title">CT1-B07.02 — NOXH HP-380</span><span class="wf-small">Trần Thị B · đã xác minh ✓</span><span class="wf-small wf-strong">13/10/2026 14:00 (GMT+7)</span><div class="wf-row" style="gap:8px;"><span class="wf-btn ok sm">Xác nhận</span><span class="wf-btn danger ghost sm">Từ chối…</span></div></div></div></div><div class="wf-drawer"><div class="wf-col" style="gap:8px;"><span class="wf-title">Từ chối yêu cầu xem nhà</span><span class="wf-small wf-strong">Lý do (người đặt đọc được) — 5 đến 500 ký tự</span><div class="wf-input filled" style="min-height:64px;">Cuối tuần này tôi đi công tác, chưa thể mở nhà.</div><div class="wf-row between"><span class="wf-small wf-muted">Gửi thông báo ngay cho Trần Thị B</span><span class="wf-small wf-muted">63 / 500</span></div><span class="wf-btn danger block">GỬI TỪ CHỐI</span></div></div></div></div></div></div><div class="wf-legend"><div class="t">Chú thích mobile</div><ol><li><span class="num">M</span><span>Picker ngày/giờ thành hàng chip cuộn ngang được; chip bị chặn vẫn hiện (kèm lý do khi chạm) để user hiểu luật, không ẩn mất.</span></li><li><span class="num">M</span><span>Nút gửi sticky dưới đáy, nhãn lặp lại slot đã chọn (&quot;13/10/2026 14:00&quot;) để chống đặt nhầm giờ. Modal từ chối thành drawer đáy, vẫn bắt buộc lý do + bộ đếm ký tự.</span></li></ol></div><h2 id="_7-bon-trang-thai-nen" tabindex="-1">7. Bốn trạng thái nền <a class="header-anchor" href="#_7-bon-trang-thai-nen" aria-label="Permalink to &quot;7. Bốn trạng thái nền&quot;">​</a></h2><div class="wf"><div class="wf-grid cols-4"><div class="wf-col"><span class="wf-state-label">LOADING</span><div class="wf-col" style="gap:8px;"><div class="wf-skeleton"><div class="wf-lines"><span class="w-40"></span><span class="w-90"></span><span class="w-60"></span></div></div><div class="wf-skeleton"><div class="wf-lines"><span class="w-75"></span><span class="w-50"></span></div></div><span class="wf-small">Skeleton theo hình card lịch; tab giữ nguyên để không nhảy layout khi dữ liệu về.</span></div></div><div class="wf-col"><span class="wf-state-label">EMPTY — TAB &quot;MÌNH ĐẶT&quot;</span><div class="wf-empty"><span class="icon">⌂</span><span class="wf-title">Bạn chưa đặt lịch xem nhà nào</span><div class="wf-text">Chọn tin đang bán rồi đặt giờ trong khung 08:00–20:00, trước ít nhất 24 giờ.</div><span class="wf-btn primary">Tìm nhà → SC-02</span></div></div><div class="wf-col"><span class="wf-state-label">EMPTY — TAB &quot;MÌNH NHẬN&quot;</span><div class="wf-empty"><span class="icon">▤</span><span class="wf-title">Chưa có ai đặt lịch xem tin của bạn</span><div class="wf-text">Khi có yêu cầu, bạn sẽ nhận thông báo và cần phản hồi trong 24 giờ.</div><span class="wf-btn">Xem tin của tôi → SC-23</span></div></div><div class="wf-col"><span class="wf-state-label">ERROR</span><div class="wf-error-box"><span class="wf-title">Không tải được lịch xem nhà</span><div class="wf-text" style="margin:6px 0;">Lịch đã đặt vẫn được giữ — thử lại, đừng gửi yêu cầu mới liên tiếp.</div><span class="wf-btn block">Thử lại</span><span class="wf-trace">traceId a1b2c3 — đọc mã này khi gọi CS 1900-xxx</span></div></div></div></div><div class="wf-legend"><div class="t">Chú thích</div><ol><li><span class="num">15</span><span>Hai tab có empty khác nhau (người mua vs chủ nhà) — đừng dùng chung một câu. Hộp lỗi nhắc &quot;đừng gửi liên tiếp&quot; vì endpoint đặt lịch giới hạn 10 lần/giờ/user. <span class="ref">docs/05 §1.4</span> <span class="ref">docs/06 §3</span></span></li></ol></div><h2 id="_8-checklist-designer-khi-dung-figma-cho-sc-27" tabindex="-1">8. Checklist designer khi dựng Figma cho SC-27 <a class="header-anchor" href="#_8-checklist-designer-khi-dung-figma-cho-sc-27" aria-label="Permalink to &quot;8. Checklist designer khi dựng Figma cho SC-27&quot;">​</a></h2><ul><li>[ ] Đủ layout: desktop (list + sidebar đặt lịch) / tablet 768 (sidebar xuống dưới) / mobile 360 (chip picker + CTA sticky)</li><li>[ ] Hai tab rõ ràng: &quot;Mình đặt&quot; / &quot;Mình nhận&quot;, đếm số trong nhãn tab</li><li>[ ] Card lịch đủ: tin + mã căn · slot GMT+7 · chủ nhà/người đặt + đã xác minh · mã lịch · badge trạng thái · hành động theo trạng thái</li><li>[ ] Đủ 6 trạng thái: PENDING / CONFIRMED / COMPLETED / REJECTED (kèm lý do) / CANCELLED / EXPIRED</li><li>[ ] Bộ đếm hạn mức &quot;X / 3 lịch chờ&quot; + trạng thái 3/3 với message nguyên văn <code>VIEWING_LIMIT</code></li><li>[ ] Picker: ngày hôm nay &amp; trước mốc +24h disabled · ngoài 08:00–20:00 disabled · quá 14 ngày disabled · mỗi ô chặn có tooltip lý do</li><li>[ ] Inline error <code>VIEWING_SLOT_INVALID</code> nguyên văn docs/06 §5 ngay dưới picker</li><li>[ ] SLA chủ nhà 3 mức: ok / soon (≤ 4 giờ) / over (quá 24 giờ) — quá SLA không disable nút</li><li>[ ] Modal từ chối: textarea bắt buộc 5–500 ký tự + bộ đếm + nút disabled tới khi hợp lệ + ghi rõ người đặt đọc được</li><li>[ ] Dialog hủy phía người mua (không hoàn tác) và nút &quot;Đánh dấu hoàn tất&quot; chỉ mở sau giờ hẹn</li><li>[ ] Địa chỉ đầy đủ chỉ hiện từ CONFIRMED trở lên; không lộ số điện thoại hai bên</li><li>[ ] Gate KYC 403 với message nguyên văn + CTA sang SC-21</li><li>[ ] Hai empty state khác nhau cho hai tab</li><li>[ ] Không emoji làm icon production (🔔/✓/⌂/▤ trong wireframe chỉ là placeholder vị trí)</li><li>[ ] Accessibility: chip ngày/giờ là button thật có <code>aria-disabled</code> + mô tả lý do, modal có focus trap và thoát bằng Esc, badge trạng thái không chỉ dựa vào màu, contrast AA</li></ul><div class="info custom-block"><p class="custom-block-title">Góp ý màn này?</p><p>Comment ngay bên dưới — ghi rõ khu vực (số callout) và đề xuất. Thay đổi nghiệp vụ cần PM duyệt trên docs/08 trước.</p></div>',27)])])}const r=a(i,[["render",t]]);export{f as __pageData,r as default};
